def lift_row_id:
  if (.properties | type) == "object" and (.properties | has("id"))
  then .properties |= (with_entries(if .key == "id" then .key = "_emodnetRowId" else . end))
  else . end;
if .type == "FeatureCollection" then .features |= map(lift_row_id) else lift_row_id end

